# Generate K_{7,7} as a maximal triangle-free graph on 14 vertices
# Part A: vertices 0-6, Part B: vertices 7-13
edges = []
for u in range(7):
    for v in range(7, 14):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Verify it's triangle-free
def is_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return False, (u, v, w)
    return True, None

triangle_free, triangle = is_triangle_free(edges, 14)
print(f"Triangle-free: {triangle_free}")
if not triangle_free:
    print(f"Triangle found: {triangle}")

# Verify it's maximal (adding any non-edge creates a triangle)
def is_maximal_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all non-edges
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # Try adding edge (u, v)
                # Check if this creates a triangle
                creates_triangle = False
                for w in range(n):
                    if w != u and w != v:
                        if w in adj[u] and w in adj[v]:
                            creates_triangle = True
                            break
                if not creates_triangle:
                    return False, (u, v)
    return True, None

maximal, non_maximal_edge = is_maximal_triangle_free(edges, 14)
print(f"Maximal: {maximal}")
if not maximal:
    print(f"Can add edge without creating triangle: {non_maximal_edge}")
